// Block (composition) — cart line items, totals, and a primary checkout action.
import { Fragment, type Ref } from "react";
import { Button } from "../components/Button";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./CartSummary.css";

export interface CartSummaryProps {
  items: { id: string; name: string; quantity: number; price: string }[];
  subtotal: string;
  total: string;
  shipping?: string;
  onCheckout?: () => void;
  checkoutLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function CartSummary({
  items,
  subtotal,
  total,
  shipping,
  onCheckout,
  checkoutLabel = "Checkout",
  className,
  ref,
}: CartSummaryProps) {
  return (
    <Stack
      as="section"
      ref={ref}
      gap="small"
      aria-label="Cart summary"
      className={className ? `sd-cartsummary ${className}` : "sd-cartsummary"}
    >
      {items.map((item) => (
        <Fragment key={item.id}>
          <Stack direction="row" justify="between" gap="small" className="sd-cartsummary__row">
            <span className="sd-cartsummary__item sd-type-body-medium">
              {item.name} × {item.quantity}
            </span>
            <span className="sd-cartsummary__price sd-type-body-medium">{item.price}</span>
          </Stack>
        </Fragment>
      ))}
      <Separator />
      <>
        <Stack direction="row" justify="between" align="baseline" gap="small" className="sd-cartsummary__row">
          <span className="sd-cartsummary__label sd-type-label-medium">Subtotal</span>
          <span className="sd-cartsummary__price sd-type-body-medium">{subtotal}</span>
        </Stack>
      </>
      {shipping !== undefined && (
        <>
          <Stack direction="row" justify="between" align="baseline" gap="small" className="sd-cartsummary__row">
            <span className="sd-cartsummary__label sd-type-label-medium">Shipping</span>
            <span className="sd-cartsummary__price sd-type-body-medium">{shipping}</span>
          </Stack>
        </>
      )}
      <>
        <Stack direction="row" justify="between" align="baseline" gap="small" className="sd-cartsummary__row">
          <span className="sd-cartsummary__total-label sd-type-label-medium">Total</span>
          <span className="sd-cartsummary__total-value sd-type-headline-medium">{total}</span>
        </Stack>
      </>
      {/* usage: completing-action — checkout ends the summary; it is a plain Button, not a submit */}
      <Button
        variant="primary"
        size="large"
        onPress={onCheckout}
        className="sd-cartsummary__checkout"
      >
        {checkoutLabel}
      </Button>
    </Stack>
  );
}

/* CartSummary.css — .sd-cartsummary (Block)
   Arrangement only: a compact commerce section that fills the column it is given. */
.sd-cartsummary {
  width: 100%;
}

.sd-cartsummary__item {
  min-width: 0;
}

.sd-cartsummary__price {
  flex: none;
}

.sd-cartsummary__checkout {
  width: 100%;
}
